(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,379195,e=>{"use strict";var i=e.i(843476),l=e.i(811337);function n(e){let n={li:"li",p:"p",strong:"strong",ul:"ul",...(0,l.useMDXComponents)(),...e.components},{AnketaCollapse:r,AnketaGroup:c,AnketaList:d,AnketaPoint:h,AnketaProse:j,Whisper:x}=n;return r||s("AnketaCollapse",!0),c||s("AnketaGroup",!0),d||s("AnketaList",!0),h||s("AnketaPoint",!0),j||s("AnketaProse",!0),x||s("Whisper",!0),(0,i.jsxs)(c,{children:[(0,i.jsx)(r,{title:"Общая информация",defaultOpen:!0,children:(0,i.jsxs)(d,{children:[(0,i.jsxs)(h,{title:"Имя персонажа [русс|англ]",children:[(0,i.jsx)(n.p,{children:(0,i.jsx)(n.strong,{children:"Мария Боттичелли | Maria Botticelli"})}),(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"«Мадам Буджардини» — прозвище, пришедшее из прошлого, известное лишь самым любимым клиентам кумо;"}),"\n",(0,i.jsx)(n.li,{children:"«Зеркальная обольстительница» — прозвище, полученное в Энкраже."}),"\n"]})]}),(0,i.jsx)(h,{title:"Возраст",children:(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"прожитый на земле: 57 лет."}),"\n",(0,i.jsx)(n.li,{children:"дата рождения — 14 ноября 1540 года. | смерти — 20 октября 1598 года."}),"\n",(0,i.jsx)(n.li,{children:"прожитый в Загробном мире как грешная душа: 420 лет"}),"\n"]})}),(0,i.jsx)(h,{title:"Пол",children:(0,i.jsx)(n.p,{children:"Женский"})}),(0,i.jsxs)(h,{title:"Раса",children:[(0,i.jsx)(n.p,{children:"Кумо."}),(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"Мария, как и все представители ее расы, не только очаровывает грешников своей красотой, заманивая их в свои сладостные объятия с вполне ясным продолжением, но и является истинным порождением двух эмоций — страсти и вожделения. Она нередко использует грешников для удовлетворения собственных потребностей, но стоит ей в процессе хоть как-то заинтересоваться партнёром «на одну ночь», у нее начинается крайняя увлеченность. Следуя за своим новым «возлюбленным» из тени она изучает красоту его или же ее тела, голоса, запаха. Она проявляет дичайшую ревность по отношению к тем, к кому она привязалась. Порой эта ревность может довести до беды не только тех, кто решил «посягнуть» на новое сокровище паучихи, но и для нее самой. Для нее оболочка, в которой заключена ее душа, лишь инструмент, благодаря которому она питается и удовлетворяет все свои желания и потребности. Для нее главным во взаимоотношениях являются любовные утехи, которые никогда не переходят в разряд разговоров по душам. То, что скрыто под ее плотью, никогда не должно быть тронуто грешником, ведь душа для кумо столь дорога, что ее великолепие никто не достоин лицезреть, не говоря уже о том, чтобы хоть как-то на нее влиять. Мария готова пойти на акт повторного самоубийства, дабы никто и никогда так и не узнал, что было скрыто телесной оболочкой прекрасной девы-паука."}),"\n"]})]})]})}),(0,i.jsxs)(r,{title:"Психологический профиль",children:[(0,i.jsx)(r,{title:"Характер",children:(0,i.jsxs)(j,{children:[(0,i.jsx)(n.p,{children:"Мария Боттичелли необыкновенной красоты женщина, чья нередкая улыбка способна даровать уверенность и принятые эмоции, превосходно выглядит в глазах тех, кому не чуждо покупать удовольствие. Она красива, элегантна и обворожительна, рядом с ней всегда витает некая аура дружелюбия, таящая в себе нечто страшное, но до жути манящее. Многим сразу же становится понятно, что это обворожительная дама — представительница расы кумо, именно поэтому ее речи и деяния медленно соблазняют грешника, заставляя его хотеть стоящую перед ним женщину, или же мужчину. Она одним лишь словом начинает заманивать понравившегося ей грешника в ловушку ложной дружбы, связывая руки паутиной лести и постепенно выпивая его духовную энергию. Первое время попавшийся даже не замечает, что эта особа начинает занимать некое место внутри его потаённого сердца. Мария продолжает пить энергию до тех пор, пока жертва не станет настолько непригодной и обыденной, что от нее будет больше проблем, чем наслаждения. Те немногие, что попали в число этих несчастных и выбрались из-под влияния паучихи, часто говорят, что ощущают себя рядом с ней сухим листом, который, поддавшись порыву ветра, летит в неизвестность."}),(0,i.jsx)(n.p,{children:"Боттичелли ненавидит похожих грешников, предпочитая баловать себя различной энергией, веря в то, что прошлая жизнь и нынешние помыслы придают вкусу некую остринку. Она крайне разборчива в еде, если же вы слишком сильно ей понравитесь, то будьте готовы быть выпитым до последней капли. Ваше сознание будет затуманено ее красотой и тем наслаждением, что она способна даровать."}),(0,i.jsx)(n.p,{children:"Когда дело доходит до обыкновенной потребности в любовных утехах, кумо совершенно забывает о разборчивости, желая получить лишь тело грешника. Ей не чужды те причуды и фетиши в греховном деянии, что при жизни никто бы и не осмелился произнести вслух. Особенной популярностью она пользуется у тех, кто любит диковинное разнообразие, даже если оно требует принятие полного облика в тех случаях, когда это возможно. Те грешники, что не желают иметь дело с кумо в вопросах любовных утех, чаще всего становятся объектами одержимости Марии. Ей всегда хочется очаровать именно того, кто не готов быть очарованным ею. Она воспринимает это как игру, таким образом она дает волю своей азартной натуре, преследуя понравившегося грешника. Именно они познают с ней искреннее наслаждение, которое Боттичелли способна даровать."})]})}),(0,i.jsx)(r,{title:"Страхи",children:(0,i.jsxs)(d,{children:[(0,i.jsx)(h,{title:"Вода",children:(0,i.jsx)(n.p,{children:"Боязнь большого количества воды, данный страх пришел прямиком из детства."})}),(0,i.jsx)(h,{title:"Огнестрельное оружие",children:(0,i.jsx)(n.p,{children:"Огнестрельное оружие, ибо это то, что так и не смогла полюбить кумо, ведь от этих «адских приспособлений» ее колотит, слишком громкие звуки и неспособность дать достойный отпор никогда никого не радовали."})}),(0,i.jsx)(h,{title:"Открыть душу",children:(0,i.jsx)(n.p,{children:"Открыть кому-либо свою душу, ведь ее она ценит больше всего. Кумо часто говорит, что единственное, что у нее осталось, это душа, что является чистейшей иронией, ведь при жизни именно душу она ценила меньше всего."})}),(0,i.jsx)(h,{title:"Повстречать мужа",children:(0,i.jsx)(n.p,{children:"Повстречать мужа, которого она убила. Даже после смерти и перерождения напоминание о годах, прожитых с ним, терзает ее плоть — обручальное кольцо намертво вросло в палец несчастной Марии, причиняя пульсирующую боль."})}),(0,i.jsx)(h,{title:"Не обрести желаемое",children:(0,i.jsx)(n.p,{children:"Не обрести то, чего по-настоящему она страстно желает, то, что поистине ее влечет к себе."})}),(0,i.jsx)(h,{title:"Иная судьба",children:(0,i.jsx)(n.p,{children:"Мария боится того, что ее судьба могла выглядеть иначе. Она действительно переживает, что она могла бы быть счастлива и без работы в борделе, мужа-насильника и ее кузена."})}),(0,i.jsx)(h,{title:"Чувства мужа",children:(0,i.jsx)(n.p,{children:"Кумо боится узнать, что же чувствовал ее муж, истекая кровью от порезов и захлебываясь водой в прекрасную темную ночь."})})]})}),(0,i.jsx)(r,{title:"Мечты, цели",children:(0,i.jsxs)(j,{children:[(0,i.jsx)(n.p,{children:"Остаться в Энкраже навсегда, ведь современный мир ее совсем не устраивает."}),(0,i.jsx)(n.p,{children:"Избавиться от напоминания о муже."}),(0,i.jsx)(n.p,{children:"Стать лучшей из кумо, соблазнив и использовав как можно больше грешников."}),(0,i.jsx)(n.p,{children:"Приобретение некого социального статуса среди ее сородичей является ее ближайшей целью."}),(0,i.jsx)(n.p,{children:"Разузнать все тайны, что хранят грешники, при помощи своих маленьких друзей."}),(0,i.jsx)(n.p,{children:"Добиться от Эдоардо, которого ныне зовут Эцио, вспомнить все, что он совершил."}),(0,i.jsx)(n.p,{children:"Провести еще хотя бы одну ночь в объятиях столь горячего «любимого» ею кузена."}),(0,i.jsx)(n.p,{children:"Разузнать, что случилось с ее работницами, помочь им по возможности."})]})}),(0,i.jsx)(r,{title:"Биография (при жизни)",children:(0,i.jsxs)(j,{children:[(0,i.jsx)(n.p,{children:"Мария Бонмарито родилась в семье бедного купца, который, во время плавания с целью продажи нескольких товаров, погибает во время кораблекрушения. Мать Марии вскоре заболевает и покидает мир живых вслед за супругом, оставляя свою дочь на попечение сестре и ее мужу. Семья Буджардини торговала травами, которые Алонзо, отец семейства, привозил из заграницы, иногда просто скупая товар у собственных соседей на рынке. Его жена, Андреа, была из семьи бедных купцов, делом которых управлял отец Марии, поскольку значительную часть семейства Бонмарито повесили на городской площади, чтобы больше никто не смел открыто высказываться о властях, пытаясь трактовать собственные правила. К величайшему сожалению ее сына и любящего мужа, женщина впала в глубокую депрессию, а в связи с вынужденным попечительством над племянницей ее состояние ухудшилось."}),(0,i.jsx)(n.p,{children:"В первые несколько лет жизни в семье тети Мария испытала на себе три попытки неосторожного убийства. Андреа и Алонзо не желали ей зла до тех пор, пока на ее счету были деньги, которые они тратили. Старшему ребенку семьи, мальчику и наследнику бедного семейного дела, уже было восемь лет, ему полюбилась маленькая сестренка, из-за чего в итоге от нее решили не отказываться, а выгодно отдать в другую семью в будущем. Несмотря на бедствующее положение купцов, они все же наняли для кормления и воспитания специальную няню, которая была лишь простой крестьянкой. В это же время своего сына Эдоардо они пытались одевать в дорогие ткани, не жалея ни одной золотой монеты на учителей, которые помогали мальчику осваивать несколько языков, счет и каллиграфическое письмо. До пяти лет Марию воспитывала ее кормилица, которая не заморачивалась над тем, чтобы воспитать в ней элегантность, которую так любили мужчины. Дальнейшим воспитанием все же занялась тетя, чтобы сэкономить на нежеланном члене семьи, обучая девочку на протяжении следующих пяти лет, как следует вести себя в обществе так, чтобы выгоднее себя продать в будущем. Она обучила ее чтению и письму и литературе на итальянском и французском языках, привив любовь к ярким цветам в одежде. Десятилетняя девочка носила на себе не новые платья, а те, что тетя перешивала из собственных, уже негодных одежд, больше похожих на тряпки."}),(0,i.jsx)(n.p,{children:"Что Мария, что Эдоардо были талантливыми, они были способными и желали учиться."}),(0,i.jsx)(n.p,{children:"Когда старший сын семьи был уже достаточно взрослым для брака, его скоропостижно заставили ухаживать за Антонелли Беатриче, очень влюбчивой девушкой из достаточно небедной купеческой семьи. Невесткой она была бы превосходной: Антонелли была почтительна, скромна, порой составляла компанию Марии, к которой питала истинное сочувствие. К сожалению, одного лишь сочувствия ей было до боли мало, ведь ей хотелось гораздо большего. Уже в десять лет она была обделена тем, что было у ее кузена и всей семьи, включая глупую и необразованную бабушку. Альба была необразованна и с трудом писала свое имя, хоть причина была вовсе не в безграмотности. В юной девочке начала цвести мечтательность и зависть, с которой она смотрела почти на всех окружающих. Когда Марии исполнилось четырнадцать, она начала расцветать словно поздний цветок. С каждым днем она становилась все краше и краше, приковывая взгляды мальчишек и, чего уж таить, некоторых мужчин."}),(0,i.jsx)(n.p,{children:"Она не могла не замечать эти взгляды, они ее восхищали и в некотором плане даже удовлетворяли. В один из вечеров, когда Мария читала молитву, совершенно не веря в то, что произносит, к ней в комнату зашел Эдоардо. Красивый, добрый и очень близкий ей человек, в котором она возможно видела не только кузена, но и нечто большее. В тот вечер она решила впервые опробовать свои женские «чары» на молодом мужчине, прекрасно понимая, чего именно в таком возрасте хотят представители мужской части населения Венецианской Республики. В тот вечер она впервые смогла разглядеть то, что будет наблюдать до конца своей жизни — желание любовных утех в глазах. Ей было до боли интересно, что именно испытывают люди при первом поцелуе, какого это, быть с мужчиной в одной постели. Ощущая контроль над ним, Мария поняла, как именно можно манипулировать мужчинами, «… ведь они все равно что звери, кинешь им мясо — ринутся за ним в погоню». Она не смогла удовлетворить Эдоардо, желая наблюдать за сладостной мукой, что испытывает партнер. В тот вечер молодой парень ушел лишь с поцелуем на устах, радуясь тому, что его кузина станет еще одной из тех женщин, что он использовал для собственного удовлетворения."}),(0,i.jsx)(n.p,{children:"На протяжении долгих месяцев, пока кузен днем обхаживал Антонеллу Беатриче, ночью он наслаждался своей кузиной. В их отношениях не было ничего кроме долгих ночных разговоров, животных поцелуев и страстных объятий. Каждый раз наблюдая за реакцией Эдоардо, Мария понимала, что именно в теле мужчины «желает женщину». В итоге, уже к пятнадцати годам девушка, помимо поцелуев и жарких объятий, не только наблюдала за рукоблудством кузена, но и принимала активное участие, помогая ему справиться с нахлынувшими эмоциями. Однако Эдоардо слишком долго находился в статусе холостяка, из-за чего его насильно женили на той, за кем ему приходилось ухаживать на протяжении нескольких лет. В ночь перед женитьбой он насильно взял свою кузину, хотя, чего грех таить, она сама была к этому готова и ждала такого исхода."}),(0,i.jsx)(n.p,{children:"Мария была довольно ситуацией, однако молодые люди в порыве страсти не соблюдали осторожность, из-за чего ранним утром их застала прислуга, которую не так давно наняли. В этот день девушка, понимая, что может случиться с ней, призналась своей тете и дяде в греховном деянии с кузеном, надеясь на то, что они ей все простят. Но, к сожалению юной Бонмарито, служанка запросила у семьи круглую сумму за молчание, ведь это был день венчания двух «любящих сердец». Служанка получила свои деньги и уехала из города, пообещав, что будет молчать. Эдоардо женился на Антонелли, вместе с ней перебравшись в комнату для супругов в доме, игнорируя ту ситуацию, что в дальнейшем должна была произойти с его кузиной. Буджардини, не желая устраивать скандал, отложили наказание за совращение их сына, но перед этим наказали племянницу несколькими ударами кнута для лошадей. Боясь повторения ситуации, Марию было принято отправить в другой дом, где ее бы никто не видел. Точнее говоря, так немолодая пара торговцев обусловилась говорить тем немногим знакомым, которые были заинтересованы в девочке."}),(0,i.jsx)(n.p,{children:"Поскольку семейство Буджардини не купалось в деньгах, а те деньги, что будут получены семьей после определенного времени проживания у них невестки, будут потрачены на налаживание торговли, было принято крайне выгодное решение. Марию продали в бордель на самой окраине города в улочке для бедных слоев общества, чтобы там ее никто не смог найти. Самыми первыми эмоциями, что испытала юная девушка, были шок, кошмарнейший стресс и непонимание, которые вскоре сменились на дичайший гнев и ненависть. Первые несколько недель она пыталась сбежать, однако, каждый раз ее отталкивали вышибалы данного заведения, что часто в качестве оплаты принимали натуру. Хозяйка борделя была относительно дружелюбна, поэтому первые полгода Бонмарито выполняла лишь работу прачки и служанки, нередко привлекая к себе внимание пьяных постояльцев. Лишь на седьмой месяц проживания и работы в борделе девушку стали обучать хитростям и умениям удачной проститутки с целью вытягивания из постояльца как можно больше денег."}),(0,i.jsx)(n.p,{children:"Мария учила то, что ей говорили, нехотя, ненавидя себя за то, что она подчиняется «кучке дешевых проституток». Старшие работницы борделя также просвещали ее о литературе и простейшей философии — уже тогда посетители ценили умных бабочек больше глупых. Ее будоражили ночи, когда она, пытаясь заснуть, слышала стоны своих будущих коллег и их клиентов, которые затем приходили снова и снова и снова, самые отважные даже делали предложения руки и сердца понравившейся им особе. Но никто никогда не уходил, прекрасно понимая, что после борделя им будет некуда деваться. Подготовку к своему «дебюту» Мария проводила на самонадеянных парнишках, что часто гуляли рядом с домом любви, надеясь на то, что мир над ними сжалится и позволит им насладиться женщиной. Нет, она их не отлавливала и не соблазняла, хозяйка борделя платила самому хорошенькому на ее вкус «мальчонке» за то, что ему приходилось испытать на себе все прелести практики будущей «богини любви». В те дни, когда парнишки не приходили, Марии приходилось ублажать вышибал, чьи глаза всегда смотрели с равнодушием, а тело с диким энтузиазмом. За месяц до начала ее практических занятий на мужчинах, ее стали поить специальными травяными настойками, что вредили организму, из-за чего многие девочки лежали с отравлениями. В то время не было средств защиты, кроме как принятия настойки трав, чтобы в конечном итоге вызвать бесплодие."}),(0,i.jsx)(n.p,{children:"В «дебют» Марии по правилам заведения все девушки и женщины, кроме нее, носили маски, скрывая свои лица для того, чтобы клиенты обращали свое внимание на молодую шестнадцатилетнюю девушку, что ходила лишь в корсете с тоненькой юбкой, голыми ступнями и руками. В тот день, в первый день официального вступления на должность проститутки, ее сняли двое мужчин, которые, по окончанию оплаченной услуги, попутно избили девушку, за что позже прилично доплатили. Эти двое в будущем станут постоянными клиентами Марии, благодаря которым она сможет оказывать экзотические услуги посетителям борделя. Будущей кумо нравился не столько процесс слияния двух или же нескольких тел воедино, сколько взгляды мужчин, в которых читалась страсть и желание."}),(0,i.jsx)(n.p,{children:"Мария до двадцати лет работала в этом борделе под чужим именем, которое по бумагам ей подделали некие знакомые ее бывшей семьи с красивой фамилией Валуа, потомственные священники из Франции. За пять с половиной лет работы над обольщением и ублажением мужчин Мария совершенно забылась, получив то, чего у нее могло и не быть. Она была рада тому, что ее продали в место, где она получала наслаждение и необходимое восхищение ею, ведь мужчины часто обожествляли ее образ проститутки, говоря, что она творит настоящие чудеса. Бонмарито была счастлива ровно до того момента, когда в ее родной бордель вошел до безобразия пьяный Эдоардо, ее первый мужчина, благодаря которому она была предана и продана собственными родственниками. Мария испытывала крайне странные чувства, одновременно радуясь его приходу и желая избить его и захоронить под тоннами лошадиного навоза, чтобы он стал удобрением. Но не одна она была той, кто заметил старого знакомого, Эдоардо также заметил ее, пошатываясь приближаясь к кузине, которую он был намерен снять на ночь. Девушка, не желая устраивать возможные разборки посреди рабочего вечера с кучей клиентов, сразу же увела бывшего неудавшегося любовника в свою комнату. Конструктивного разговора не вышло, ведь ими обоими завладели те запретные чувства, что пылали много лет назад. Вот так третьим постоянным клиентом будущей кумо стал ее кузен, которого теперь она ласково называла братом."}),(0,i.jsx)(n.p,{children:"Переломным моментом в ее жизни стал мужчина по имени Филипп, который был мужчиной в возрасте, у которого не было левого глаза и нескольких пальцев на правой руке. Он являлся бывшим воякой, который был не прочь на старости лет воспользоваться накопленными средствами, чтобы насладиться юными дарованиями природы. В тот день многие девушки избегали его, то и дело пересаживаясь с колен потенциальных клиентов на диванчики, чтобы находиться как можно дальше от старца."}),(0,i.jsx)(n.p,{children:"Одна лишь Мария не брезгала работой с таким мужчиной, ведь ей старость не казалась столь большим уродством. Она смотрела на него с вызовом в глазах, ожидая, когда он сам к ней подойдет и предложит провести эту ночь вместе. К ее удивлению и восхищению, тело мужчины, что было крыто богатым костюмом, не было столь отвратительным, как она могла себе представить. Все же, карьера военного оставила свои плюсы на его теле, чему работавшая девушка была крайне рада. Его звали Филипп Боттичелли, как позже оказалось, он был одним из патрициев, что даровало ему неплохие средства для существования. Он был стар и одинок, у него не было семьи и родственников, точнее, он так говорил. Через полгода посещения борделя он сделал Марии предложение, выкупив ее у хозяйки борделя."}),(0,i.jsx)(n.p,{children:"Новая жизнь должна была обрадовать теперь уже замужнюю женщину, которая выбралась из нищеты и приобрела какие-никакие средства для существования, однако ей не хватало той комнаты, в которой она прожила пять лет, ее знакомых и коллег, которых она смело могла назвать друзьями. А также она скучала по клиентам, видимо за ее долгую работу организм привык к сладостной муке, а теперь ее вовсе не было. Но Боттичелли, не желая терять то, что она приобрела, решила отказаться от своего прошлого, хотя это было попросту невозможно. Мария смогла заняться тем, что ей действительно нравилось и было интересно — литература, история, философия, даже немного арифметики. Но с каждым месяцем со дня бракосочетания ей становилось все труднее и труднее себя сдерживать, она постоянно поглядывала на мужчин так, как раньше смотрели на нее. Через полгода после свадьбы семью Боттичелли посетил очень дальний родственник ее мужа, который был молод и хорош собой. Он был еще совсем юнец, в глазах которого Мария читала стойкое желание, а тело юноши всегда соглашалось с глазами, специфически реагируя не только на внешний вид будущей кумо, но порой и на ее голос. Она соблазнила юнца, который был на десять лет младшее нее, изменив с ним своему супругу не один раз. На протяжении целого месяца, что оставался гостить юный Агостино, они встречались каждую ночь, отдаваясь в руки желанию и похоти. В последнюю из ночей Филипп застал жену и, порядочно избив дальнего родственника, отослал его из дома, желая растянуть удовольствие от предстоящих пыток жены. Мария была готова к этому, она знала, на что идет и чем поплатится в случае раскрытия обмана, Боттичелли была полностью готова. К сожалению юной особы, с того самого дня ее муж постоянно избивал ее, не давая организму бывшей проститутки полностью восстановиться. Так продолжалось почти семь лет, пока Филипп тяжело не заболел и не слег в постель. Уже не юной Боттичелли было двадцать восемь лет, лицо ее было бледным, а на руках виднелись багряные пятна. Она впервые за семь лет не испытала на себе горячую руку мужа, за что благодарила Бога, в которого не верила. Ночами, когда ее муж начинал задыхаться, она нежно поглаживала его седую голову, улыбаясь в темноте. В дни, когда ему становилось лучше, и он начинал приходить в себя, Мария сажала к нему на лицо пойманных ею пауков, чтобы наблюдать за тем, как лицо старика корчилось от неприязни. Через несколько недель, когда надежда на выздоровление Боттичелли была утеряна, он попросил свою жену избавить him от страданий. Она с радостью собиралась исполнить волю умирающего человека. Уехав с ним на неделю ближе к морю, в темную ночь она перетащила его дряхлое тело к воде, где медленно резала ему руки и ноги, после чего скинула в воду, наблюдая за тем, как живой человек, истекающий кровью, захлебывается в воде. Это была страшная смерть, очень страшная смерть."}),(0,i.jsx)(n.p,{children:"Вернувшись в Венецию, Мария потратила большую часть имеющегося у нее состояния на крупный дом рядом с центром города, где она обустроила свой кабинет, кухню и десять спален, где на первом этаже стояло множество диванчиков и место для скрипачей."}),(0,i.jsx)(n.p,{children:"Также в доме было три подсобных помещения, где одно выступало в роли прачечной, а другие два — складом для вина и одежды. За каждой комнатой для работниц можно было подсматривать при помощи элементарных отверстий в стене, которые можно было приоткрыть в коридоре. Этот дом не был обделен неким шиком, но и назвать его богатым было нельзя, за что себя корила сама Мария. После окончательного завершения работ над будущим домом утех, Боттичелли лично отправилась в бедный район для того, чтобы найти работников. Она искала всех: девушек, юношей, зрелых женщин и мужчин. Разумеется, мужчин как работников особых услуг она не нанимала, ведь это не поощрялось законом, а значит могло вызвать проблемы."}),(0,i.jsx)(n.p,{children:"Ко дню открытия борделя в нем проживало шесть девушек из крайне бедных семей, которые попросту не могли их содержать, а также двух крепких мужчин и юного мальчика, что прислуживал чем-то на подобии лакея. За месяц до открытия Мария лично обучала девушек, демонстрируя науки соблазнения и ублажения на тех трех мужчинах, что были ею наняты ранее. Благодаря знакомым умершего мужа Боттичелли смогла найти своему борделю первых состоятельных клиентов, которые помимо денег ничего не имели. Также Боттичелли не смогла обойти самое важное для ее работниц — познания в нескольких науках, что делали ночных бабочек намного привлекательнее для статных мужчин. Это позволяло новому борделю не сталкиваться с проблемами, что могли в случае особой неудачи сильно ударить по этому месту. На удивление работниц и самой Марии, первые две недели бордель имел особый успех. В один из обычных рабочих для девушек дней случилось то, чего будущая кумо жаждала почти десять лет своей жизни, «на огонек» зашел Эдоардо Буджардини, ее кузен и бывший постоянный клиент. Мария встретила его как старого друга, оставив своих девочек одних в зале, пока те зарабатывали столь необходимые всем золотые монеты. Она проводила мужчину в свой кабинет, где расспрашивала его о том, чем он занимается, как он поживает. Как оказалось, жизнь кузена сложилась намного лучше, чем у Боттичелли, ведь его «любимая» родила ему двух сыновей, которым было уже по семь лет, а сам Эдоардо смог добиться успехов в торговом деле, благодаря чему состояние семьи сильно возросло. Эти новости сильно ударили по женщине, которая надеялась на то, что ее бывший любовник стал пьянчугой, прикончившим собственную жену и упустивший неприбыльное ранее дело. Ушел Эдоардо из борделя лишь рано утром, ведь заночевал он в кабинете своей кузины, которой всю ночь уделял особое интимное внимание."}),(0,i.jsx)(n.p,{children:"Это продолжалось на протяжении нескольких лет, Эдоардо Буджардини стал постоянным посетителем борделя, где всегда уделял свое время и деньги лишь хозяйке заведения, обходя стороной работниц. За эту связь девочки прозвали Марию «мадам Буджардини», весело шутя о том, что однажды он бросит жену и сделает предложение этой состоявшейся даме."}),(0,i.jsx)(n.p,{children:"Но в один роковой вечер в бордель ворвалась разгневанная Антонелли, которая после выяснения отношений с вышибалами узнала, что ее муж «беседует» с хозяйкой борделя. Когда же разгневанная Буджардини ворвалась в кабинет Марии, она была в шоке. Нет, она не застала мужа за изменой с его кузиной лишь благодаря хитрому уму Боттичелли, которая специально установила в кабинете колокольчик, который звонил лишь в том случае, когда в зале нужна была помощь. Это был сигнал, благодаря которому вышибалы могли вызвать хозяйку заведения. Жена кузена впала в настолько сильный шок, что все они с минуты три молчали, просто переглядываясь, после чего она села на кушетку рядом со столом, за которым сидела Мария. После долгой и выматывающей беседы, двое любовников смогли убедить женщину в том, что здесь никогда не было разврата, а лишь восстанавливались утерянные семейные узы. Отныне чета Буджардини чаще всего приходили в бордель вместе, где весело болтали с хозяйкой заведения. Однажды Антонелли предложила Марии познакомиться с детьми Эдоардо, которым было уже по двенадцать лет, но та отказалась, сказав: «Это не совсем хорошая идея, дорогая, боюсь, что детям лучше не знать о тете, которая причастна к столь греховной работе»."}),(0,i.jsx)(n.p,{children:"В какой-то период семейство Буджардини пропало, не появляясь на пороге борделя несколькими месяцами подряд. Однако в один из вечеров в одиночку пришла Буджардини, желая поговорить с кузиной мужа лично. В ходе разговора, размягченного выпивкой, Мария узнала о том, какой тяжкий груз носит на себе Антонелли, терпя не только мужа, но и детей, которых она совсем не любила. Благодаря алкоголю и довольно дружелюбно-душевным отношениям между этими двумя зажглась искра, итогом которой стала совместная ночь. Благодаря этому инциденту следующие года Марию посещали оба супруга, получая истинное наслаждение, даже не догадываясь об изменах друг другу."}),(0,i.jsx)(n.p,{children:"Тем временем бордель Марии за шесть лет работы приобрел определенный статус в обществе. О нем не говорили, им не восхищались, но большинство заинтересованных знали, что именно девушки Боттичелли способны даровать незабываемое наслаждение за приличную цену. Также данный бордель за отдельную плату был готов удовлетворить фетиши посетителей: будь то насилие, подглядывание или же переодевание. Для особенных клиентов предоставлялся особый работник-мужчина, который мог выступать как третий и очень нелишний участник греховного объединения, так и исполнять услуги гомосексуального характера. Главным событием для борделя был венецианский карнавал, во время которого стоимость услуг жриц любви понижалась и заведение за одну ночь могло посетить от тридцати мужчин. Для дополнительного заработка некоторые из девушек выходили на празднование в особой дамской маске с уникальным дизайном, где на видном месте была изображена роза в клетчатом стиле с торчащим пером, окрашенным в красный цвет."}),(0,i.jsx)(n.p,{children:"Работницы борделя Боттичелли носили такие маски и вне карнавала, поэтому во время празднеств их легко могли узнать и воспользоваться теми услугами, что они могли предложить. Такие уникальные для борделя маски были созданы гильдией масочников, с которыми владелица борделя заключила крупную сделку, за что поплатилась собственными сбережениями, которые позже окупились. Частенько в такой маске выходила и сама Мария, нередко возбуждая мужчин «случайными» прикосновениями и двусмысленными намеками. Она продолжала работать совместно со своими девушками, однако обслуживала лишь достаточно состоятельных господ, а также тех, кто слишком сильно любил оставлять побои. Чтобы сама мадам Буджардини не говорила, своих работниц она любила и уважала как собственных детей, поэтому и ухаживала за ними, не жалея ни единой золотой монеты. Безусловно, это также было полезно в работе, но крайне редко бордели могли позволить себе вызов врача в конце каждой недели. На собственном здоровье женщина экономила, поскольку вызов врача, содержание борделя, вышибал, лакея и десятерых девушек было очень и очень затратным делом. Также ей приходилось время от времени посещать стражников и вышестоящие органы власти, передавая скромный конвертик от «всего сердца». Бордели не были запрещены, но только из-за того, что так венецианцы боролись с мужеложеством, услуги которого «дом Боттичелли» оказывал, хоть это и делалось тайно и лишь самым близким из клиентов и друзей Марии."}),(0,i.jsx)(n.p,{children:"В свои сорок пять лет Мария тяжело заболела простудой, которая из-за долгого игнорирования переросла в бронхит, который позже станет хроническим. У Боттичелли не было лишних лир, из-за чего она старалась справиться с болезнью сама. Но благодаря своим работницам ее навестил врач, которого они ей оплатили. Через полгода женщина была относительно здорова, поэтому смогла намного чаще спускаться к гостям и развлекать их беседами до тех пор, пока те выбирали себе девушку на ночь. Однако после частичного выздоровления ее стала донимать одна и та же мысль: насколько же хорошо она живет? У нее нет родного дома и кровати, она уже пятнадцать лет спит в собственном кабинете на диванчике, что по совместительству использует для оказания блаженных услуг. Единственная мысль, что согревала ее, была о ее работницах, о тех женщинах, что позаботились о ней, не пожалев собственных денег."}),(0,i.jsx)(n.p,{children:"В один из обычных для борделя вечеров пришла Антонелли, которая, прервав бурные отношения с Марией, долгое время не появлялась, но частенько писала, из-за чего у них сложились действительно дружеские отношения. Как оказалось, они обе более не верили в любовь, как и в мораль, считая что мужчинам в этом мире отведена слишком большая роль. В ходе долгих бесед на протяжении долгих месяцев, Боттичелли и Буджардини заключили сделку, целью которой был Эдоардо. Женщины решили его убить, ведь обе они не утаивали своего отношения к мужчине, обеим смерть столь «любимого» ими мужчины шла на руку. Купеческое дело и управление финансами могли взять на себя ее сыновья, между которыми было строго поделено наследство, а сама Антонелли могла спокойно уйти к любовнику, которого страстно желала. Мария же в самом деле не получила бы с этого никакой выгоды, ведь одержимость им у нее пропала, а более ничего их не объединяло, помимо жарких встреч, конечно же. В один из дней совместного посещения борделя семьей Буджардини, Мария подсыпала яд в вино, что пил ее кузен. Через несколько часов он был холоден, а Антонелли развлекалась с одним из мужчин, что работал на будущую кумо. Мария же в свою очередь с интересом разглядывала труп мужчины, что даже в смерти был симпатичен собой, она возжелала лишь одну единственную частичку его плоти. Мария отрезала его мужское естество, небрежно положив репродуктивный орган с дополнением в широкую бутылку, которую позже залила вином и спрятала в ящике стола. Транспортировка трупа заняла много времени, поскольку тело мужчины нужно было пронести сквозь гостиный зал, где спали особо щедрые клиенты в обнимку с девушками. Тело вывезли какие-то рабочие, которых наняла Антонелли, и выбросили в яму, или же колодец?.. Точного ответа будущая кумо не знала и ей это было неинтересно. Лишь изредка она любовалась тем, что хранилось у нее в шкафу, вспоминая, сколько удовольствия она раньше получала. О судьбе своей подруги она знала немного, лишь пару раз видев ее с новым мужем. Сыновей своего кузена она знала хорошо, иногда навещая их дом, помогая советом или же несколькими монетами. Таким образом Мария не столько пыталась загладить собственную вину из-за смерти их отца, сколько выказывала юношам свою благосклонность. Можно сказать, что они будоражили ее кровь, ведь их сходство с отцом было весомо, но выглядели они лучше благодаря генам семейства Беатриче."}),(0,i.jsx)(n.p,{children:"С сорока восьми лет Боттичелли нашла себе редкостное развлечение, во время бесед с богатыми клиентами она устраивала некий аукцион. Раз в несколько месяцев она принаряжала своих девушек в древних богинь, оставляя часть лишь прекрасными обнаженными нимфами. Каждый, кто заходил к ним, мог поучаствовать в торгах на одну ночь, где Мария всегда перебивала слишком низкие ставки. Она давала волю некой азартности, что помогала ей чувствовать себя лучше, чем было на самом деле. Дела в борделе шли хорошо, но не так, как это было восемнадцать лет назад. Как оказалось, у дома Боттичелли оказались соперники, открывшие свои двери всем, кто мог заплатить. Превосходств у других борделей не было, за исключением цены и времени работы, ведь бордель будущей кумо работал лишь с вечера по ночь, днем он был закрыт. Девушки Марии действительно брали много за ночь, но сумма была оправдана: клиенты испивали вина, изредка наслаждались музыкой, им позволялось не уединяться с работницей, при всем желании они могли насладиться ею прямо в зале, их окружала дорогая мебель, вход всегда охранялся, из-за чего просто так попасть сюда их жены не могли. Но для скупых венецианских мужчин, любящих женщин, стоимость была важнее, из-за чего посещаемость постепенно начинала падать. Это были трудные времена, из-за которых Мария была готова начать продавать собственные драгоценности и некоторую мебель, однако ей не пришлось. Агостино Боттичелли, племянник ее бывшего мужа, которого она совратила много лет назад, вернулся в город, чтобы начать вести в нем дела. Он помнил женщину, что помогла удовлетворить его юношеское любопытство и мужские потребности, благодаря чему у борделя появился покровитель."}),(0,i.jsx)(n.p,{children:"Они были и раньше, но ни от одного из них Мария не брала деньги. Дела вновь стали налаживаться, в бордель стали приходить новые лица, порой приходя с супругами, что вызывало у Боттичелли восторженную улыбку. Ее бордель и раньше был особенным, оказывая различные услуги, но с того момента, как сюда стали ходить женатые пары, женщина самолично дала своему бизнесу имя «оплота греховности»."}),(0,i.jsx)(n.p,{children:"В пятьдесят лет она вновь сильно заболела, из-за чего в одну из дневных прогулок упала в обморок, поранив ногу о гвоздь. Вскоре этот инцидент дал осложнение на ногу, из-за которой Мария стала ходить с тростью, постоянно прихрамывая. Влажность особенно сильно влияла на ее состояние, из-за чего она временно покинула Венецию, поехав в дом ее племянника по мужу, дабы позволить себе отдохнуть. Борделем же в это время заправлял Агостино, следуя инструкции, что ему написала будущая кумо. Как выяснится позже, он действительно неплохой делец, но управление борделем требует особых качеств и условий, основным из которых являлась женщина во главе. Мария проживала в особняке Боттичелли рядом с детьми своего племянника и другими родственниками, о которых ей не поведал ее муж, каждый месяц навещая бордель. В пятьдесят три года она возвращается в Венецию, дабы вновь встать во главе собственного борделя, где все осталось прежним благодаря ее постоянным поездкам. Однако из ее работниц осталось лишь трое, семеро девушек были новенькими и «свежими». Как позже выяснилось, две из семерых женщин вышли замуж, а остальные выкупили себя и решили уйти, дабы пожить для себя, не ублажая мужчин. Все они оставили Марии письма, которые были написаны очень корявым почерком Агостино. Он писал под диктовку, ведь они все до единой были безграмотны и не хотeли смущать уже немолодую женщину своим почерком. Они могли поддержать беседу об искусстве, политической целостности республики, или же просто посплетничать. Дом Боттичелли славился умными работницами, которые ублажали как физически и морально, так и духовно."}),(0,i.jsx)(n.p,{children:"Эти семь писем до конца своей жизни будущая кумо хранила там же, где и прибыль девушек, совместно с письмами покровителям. Бордель Боттичелли еще на протяжении пяти лет активно работал, не теряя ни своей особой славы, ни красоты здания и его работниц. Однако влажный воздух, постоянная дизентерия и сложная работа вновь наградили старую женщину очередной болезнью. Из-за постоянных болей она не могла спать, ей было очень сложно слушать кого-либо или просто сидеть. В последний свой вечер она написала по письму каждой из своих старых работниц, даже тем, кто уже не работал в ее борделе. К письму прилагались деньги, что были равными стоимости собственного выкупа. Последнее письмо она оставила своему неродному племяннику, отдав в завещании ему бордель и свои средства, но лишь при условии, что он доставит все письма."}),(0,i.jsx)(n.p,{children:"Нашли мадам Боттичелли, которую всегда в шутку ее девочки называли Буджардини, в своем кресле за столом, кожа ее была бледна, а в руке была трость. Она умерла от яда, что приняла вечером, пузырек которого лежал разбитым в камине."})]})}),(0,i.jsx)(r,{title:"Жизнь в Энкраже",children:(0,i.jsxs)(j,{children:[(0,i.jsx)(n.p,{children:"Переродившись в Энкраже, Мария долго привыкала к облику молодой и юной девушки, что был ее точной копией тридцать семь лет назад. С телом паука женщина справилась относительно быстро, хотя самую первую линьку пережила трудно, как и последующие десять. Поскольку женщина стала кумо, то она продолжила свою работу, соблазняя и питаясь энергией своих клиентов и персональных любовников. Она открыла в себе способность разговаривать с пауками, что проживают в замке и за его территорией. Благодаря своим маленьким друзьям Боттичелли сведует о многих грязных секретах, что таит в себе это место. Никто не знает, откуда у нее эти сведения, но делится она ими лишь со своими самыми любимыми клиентами, которые в замен даруют ей пир из собственной энергии. А благодаря своей необычайной способности вызывать у грешников приступы нарциссизма, она получила прозвище «зеркальной обольстительницы»."}),(0,i.jsx)(n.p,{children:"Благодаря определенному успеху в делах любовных, а также в организации поставки определенных сведений третьим лицам, ей стал доверять черный рынок, позволил открыть в их истинных залах публичный дом. Мария очень ценит ту возможность, которую ей представили сильные мира сего, храня их секреты и стараясь предоставить им все, что они у нее потребуют, за разумную цену, конечно же. Черный рынок стал ее убежищем, где помимо любимой работы, ее ждут новые работники, которых она взяла под опеку своего нового Дома Боттичелли. Она питает к ним самые приятные чувства, но даже это не сможет их спасти, если они предадут ее или Черный рынок."})]})})]}),(0,i.jsxs)(r,{title:"Дополнительно",children:[(0,i.jsx)(r,{title:"Факты о персонаже",children:(0,i.jsxs)(d,{children:[(0,i.jsx)(h,{title:"Смена имени",children:(0,i.jsx)(n.p,{children:"Имя Марии сменили по бумагам из-за одной простой причины: в городах-государствах Италии нельзя было работать проституткой с именем «Мария» (и по сей день это является табу для большинства итальянцев)."})}),(0,i.jsx)(h,{title:"Встреча с детьми кузена",children:(0,i.jsx)(n.p,{children:"С детьми своего кузена-любовника она все же встретилась, но лишь через шесть лет после предложения от их матери. Встреча имела интимный характер с полугодовым продолжением в виде посещения борделя и съема работниц заведения."})}),(0,i.jsx)(h,{title:"Неспособность любить",children:(0,i.jsx)(n.p,{children:"За всю свою жизнь Боттичелли так и не смогла полюбить, однако была одержима идеей любви к кому-либо множество раз."})}),(0,i.jsx)(h,{title:"Утаивание биографии",children:(0,i.jsx)(n.p,{children:"Часть своей биографии, где она вышла замуж и терпела побои, кумо утаивает, но с большой гордостью рассказывает обо всем остальном."})}),(0,i.jsx)(h,{title:"Маска",children:(0,i.jsx)(n.p,{children:"Первый полученный ключ, способный достать элемент гардероба в Энкраже, Мария потратила на маску из ее борделя, которая является уникальной в своем роде и по сей день."})}),(0,i.jsx)(h,{title:"Письма от работниц",children:(0,i.jsx)(n.p,{children:"Второй ключ она потратила на несколько писем от ее работниц. Мария бережно их хранит, порой держа их прямо «у сердца», пряча в корсете."})}),(0,i.jsx)(h,{title:"Выкуп работниц",children:(0,i.jsx)(n.p,{children:"Все работницы борделя были выкуплены у их отцов, поэтому все их документы принадлежали Марии. Получить их обратно можно было лишь выкупив себя."})}),(0,i.jsx)(h,{title:"Любовь к работницам",children:(0,i.jsx)(n.p,{children:"Всех работниц кумо ценила и любила как дочерей, из-за чего им было дозволено выходить из борделя на прогулки определенное количество раз в неделю. Каждая из них могла выкупить себя, выплатив женщине две с половиной тысячи лир."})}),(0,i.jsx)(h,{title:"Тайник с реликвией",children:(0,i.jsx)(n.p,{children:"Мужское естество своего кузена в вине Мария перед смертью спрятала в тайнике под столом, дабы приковать Эдоардо к этому месту. Вместе с бутылкой она положила туда кольцо, что он ей подарил. Быть может, это был ее личный способ приковать душу бывшего любовника к себе."})}),(0,i.jsx)(h,{title:"Наследие борделя",children:(0,i.jsx)(n.p,{children:"Одна из оставшихся работниц вышла замуж за овдовевшего Агостино и возглавила бордель, повесив в кабинете портрет Марии Боттичелли, дабы ту всегда помнили как истинную владелицу и вечную покровительницу этого дома."})}),(0,i.jsx)(h,{title:"Четыре буквы «Б»",children:(0,i.jsx)(n.p,{children:"После перерождения Мария лично для себя обозначила, что четыре буквы «Б» ведут к неминуемым страданиям — Бонмарито, Буджардини, Боттичелли, Беатриче. Ей отчасти противно осознавать факт того, что она привязала к фамилиям ее семей бедствия, но поделать с этим она ничего не смогла."})})]})}),(0,i.jsx)(r,{title:"Внешность",children:(0,i.jsxs)(j,{children:[(0,i.jsx)(n.p,{children:"Перед самой своей смертью Мария Боттичелли, некогда одна из самых красивых женщин Венецианской Республики, была безобразна. В силу возраста и болезней, что она запустила до того состояния, пока они не становились слишком критическими, в свои почти шестьдесят лет будущая кумо выглядела действительно плохо. В ее глазах не было блеска, кожа обвисла, она хромала и голос ее был хрипловат."}),(0,i.jsx)(n.p,{children:"В Энкраже она переродилась словно феникс — после смерти старой оболочки она возродилась в новой, молодой версии себя самой. Ее спина выпрямилась, приобретя присущую ей полу-благородную осанку, благодаря чему можно было выделить ее высокий рост, почти что метр семьдесят пять сантиметров. Лицо и тело Боттичелли выглядели так, словно ей вновь было двадцать лет, как в те времена, когда она испытывала наслаждение от внимания мужчин и когда ей не приходилось слишком много думать. Быть может, Мария выглядит так именно из-за того, что в глубине души понимает, что именно в этом возрасте ей почти не приходилось страдать и делать вид сильной и самодостаточной женщины? Отныне ее кожа блистает здоровым румянцем, что является относительной редкостью среди жительниц мира мертвых, ведь они все чем-то похожи на блуждающих призраков. Будь это аристократы, что пользуются столь любимой ими пудрой, или же те, чей облик продиктован особенностями души — они все для Марии выглядят больными, из-за чего она порой испытывает дискомфорт."}),(0,i.jsx)(n.p,{children:"Лицо ее всегда украшено улыбкой темно-вишневых губ, которые выделяют ее здоровые, белые зубы. Смерть и перерождение не отменили ее мнения насчет красоты тела, поэтому она все также продолжает пользоваться косметикой, благодаря чему всегда выглядит превосходно. Ее серые глаза порой смотрят прямо в душу, в иных же ситуациях в них читается желание и что-то очень странное, манящее и пугающее лишь тогда, когда грешная душа решается отвести взгляд. Одного взгляда в эти глаза достаточно для того, чтобы образ кумо отпечатался в памяти, плетя в нем паутину желания, что медленно окутывает жертву. Лицо женщины обладает очень нежными, немного по-детски ангельскими чертами, даруя ей милый и чуткий образ. Ее движения нежны, словно она каждый раз касается чего-то столь хрупкого, что от одного неверного движения это что-то разобьется, но стоит ее партнеру по греховному деянию возжелать в ее образе грубости, как она меняется. Даже ее жестикуляция может источать в себе некую ауру жестокости и хладнокровия, хотя это было ей не присуще при жизни даже после убийства собственного мужа. Единственным изъяном ее внешности является безымянный палец левой руки, в который вросло кольцо из светлого металла, почерневшего за те века, которые кумо провела в этом мире. Этот палец выглядит болезненно, иногда Мария действительно ощущает боль, из-за чего прикрывает эту руку перчаткой."}),(0,i.jsx)(n.p,{children:"В обличье мужчины ее рост остается прежним, однако меняются ее анатомические особенности. Нежные черты лица пропадают, сменяясь резкими и холодными так, словно их слепил скульптор на собственном «холсте». Это недалеко от правды, ведь этот облик Боттичелли создала сама, совершенствуя его уже на протяжении четырех веков, лепя «идеального» мужчину. Этот образ отчасти был взял от ее любовника и кузена, в особенности нижняя часть."}),(0,i.jsx)(n.p,{children:"В неполном обличье своей расы Мария выглядит как зеркальный паук под два метра шириной с учетом лап и четыре метра высотой, из туловища которого растет человеческое тело мертвенно-белого цвета. Самым примечательным является ее брюшко, которое покрыто отражающим свет пигментом, благодаря чему оно является зеркальным."})]})}),(0,i.jsx)(r,{title:"Навыки и умения",children:(0,i.jsxs)(d,{children:[(0,i.jsx)(h,{title:"Языки",children:(0,i.jsx)(n.p,{children:"Мария понимает и владеет письмом на английском, французском и итальянском (венецианский диалект) языках. Также она владеет языком немых, которым, как и английским, овладела в Энкраже."})}),(0,i.jsx)(h,{title:"Финансовая грамотность",children:(0,i.jsx)(n.p,{children:"Кумо владеет пусть и слабой, но финансовой грамотностью, которая была актуальна в шестнадцатом веке. Она, как владелица достаточно крупного борделя, принимала непосредственное участие в экономической состоятельности города."})}),(0,i.jsx)(h,{title:"Пение, танцы, философия",children:(0,i.jsx)(n.p,{children:"Пение и танцы, философия, история и литература — лишь крупицы знаний, которыми владела Мария, также как и все ее работницы."})}),(0,i.jsx)(h,{title:"Верховая езда",children:(0,i.jsx)(n.p,{children:"Верховая езда, которая в Энкраже ей так и ни разу не пригодилась."})}),(0,i.jsx)(h,{title:"Наблюдательность",children:(0,i.jsx)(n.p,{children:"Наблюдательность, Мария словно паук смотрит за всем происходящим из тени, выжидая момент, когда сможет появиться."})}),(0,i.jsx)(h,{title:"Обаяние",children:(0,i.jsx)(n.p,{children:"Необычайное обаяние позволяет ей соблазнять понравившуюся ей «еду»."})}),(0,i.jsx)(h,{title:"Плетение паутины",children:(0,i.jsx)(n.p,{children:"Плетение паутины."})}),(0,i.jsx)(h,{title:"Проницательность",children:(0,i.jsx)(n.p,{children:"Обладает редкой проницательностью, благодаря которой располагает к себе различных грешников."})}),(0,i.jsx)(h,{title:"Флора Энкража",children:(0,i.jsx)(n.p,{children:"Немного разбирается в флоре Энкража, готовя снотворные снадобья для своей «еды»."})}),(0,i.jsx)(h,{title:"Виноделие",children:(0,i.jsx)(n.p,{children:"Разбирается в винах, называя это издержкой профессии. Хочет опробовать себя в виноделии, но на данный момент не имея под рукой специалиста флоры Энкража, этого не делает. Все же тех, кто владеет достаточными знаниями о флоре, не так много, а требования их связи с этим дороговаты."})})]})}),(0,i.jsx)(r,{title:"Слабости",children:(0,i.jsxs)(d,{children:[(0,i.jsx)(h,{title:"Огонь",children:(0,i.jsx)(n.p,{children:"Мария остерегается огня и тех, кто им владеет. Огненная стихия — это не ее «конек»."})}),(0,i.jsx)(h,{title:"Яркий свет",children:(0,i.jsx)(n.p,{children:"Яркий свет способен ослепить кумо, однако слабый свет сильно привлекает ее, в таких местах она старается оставить свою паутину."})}),(0,i.jsx)(h,{title:"Колебания паутины",children:(0,i.jsx)(n.p,{children:"Любые звуки, что приводят к колебаниям паутины, противны Марии и режут ее слух, из-за чего та старается избегать чрезмерно музыкальных мест. Это оставляет ей большую рану в сердце, ведь при жизни она слушала скрипку."})}),(0,i.jsx)(h,{title:"Высокочастотные звуки",children:(0,i.jsx)(n.p,{children:"Высокочастотные звуки способны временно оглушить кумо, вызвав дезориентацию. Все грешники, что когда-либо использовали эту особенность против нее, попадают в «черный» список Боттичелли."})}),(0,i.jsx)(h,{title:"Ядовитый дым",children:(0,i.jsx)(n.p,{children:"Ядовитый дым временно выводит из строя Марию, если она находится в неполном облике."})}),(0,i.jsx)(h,{title:"Прожорливость",children:(0,i.jsx)(n.p,{children:"Чрезмерная прожорливость — та причина, по которой большинство грешников избегают собратьев Марии, ведь все кумо настолько жадны в еде, что могут полностью осушить грешника. Если женщина долгое время не будет питаться духовной энергией, она начнет слабеть, что может привести к ее смерти. В ином же случае она начнет охоту за энергией, что будет не самым приятным зрелищем."})}),(0,i.jsx)(h,{title:"Старческая внешность",children:(0,i.jsx)(n.p,{children:"Все грешники, что обладают старческой внешностью, вызывают в Марии потаённый страх мужа, из-за чего она предпочитает избегать таковых. Они единственные, кому она отказывает в предоставлении своих услуг."})}),(0,i.jsx)(h,{title:"Линька",children:(0,i.jsx)(n.p,{children:"Линька — это настоящее испытание для кумо, причем далеко не самое приятное."})}),(0,i.jsx)(h,{title:"Одержимость",children:(0,i.jsx)(n.p,{children:"Марии свойственно быть одержимой кем-либо, это может доходить до сталкерства и неуместной ревности."})}),(0,i.jsx)(h,{title:"Воспоминания о борделе",children:(0,i.jsx)(n.p,{children:"Порой страдает воспоминаниями о собственном борделе, о своих работницах. Еще при жизни у нее болело сердце за девушек, что работали под ее началом, после смерти моральные муки и волнения усилились."})})]})}),(0,i.jsx)(r,{title:"Связанные персонажи",children:(0,i.jsxs)(d,{children:[(0,i.jsx)(h,{title:"Филипп Боттичелли (Немо Олливан)",children:(0,i.jsx)(n.p,{children:"Людской мир. Муж, ныне — Немо Олливан, 22 года. Связывает обручальное кольцо, являющееся символом закрепленного брачного союза. Данный предмет врос в палец женщины, напоминая кумо пульсирующей болью о ее муже."})}),(0,i.jsx)(h,{title:"Эдоардо Буджардини (Эцио Ритторо)",children:(0,i.jsx)(n.p,{children:"Людской мир. Кузен, ныне — Эцио Ритторо, 32 года. Связывает кольцо."})})]})})]}),(0,i.jsx)(x,{children:(0,i.jsx)(n.p,{children:"Женская красота все равно что кинжал, главное уметь им пользоваться и ваша жертва падет ниц. Тело лишь инструмент в борьбе за желаемое, никогда этого не забывайте…"})})]})}function s(e,i){throw Error("Expected "+(i?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}e.s(["default",0,function(e={}){let{wrapper:s}={...(0,l.useMDXComponents)(),...e.components};return s?(0,i.jsx)(s,{...e,children:(0,i.jsx)(n,{...e})}):n(e)}])}]);